const X0 = 60, X1 = 700, Y0 = 480, Y1 = 40;
const L = (w) => w * w / 2;

export function evaluate({ inputs }) {
  const eta = parseFloat(inputs.eta);
  const k = Math.round(sdk.clamp(inputs.step, 0, 8));
  const f = 1 - eta;
  const big = eta > 2;
  const wMax = big ? 7 : 3.5;
  const lMax = big ? 23 : 6.5;
  const X = sdk.linear([-wMax, wMax], [X0, X1]);
  const Y = sdk.linear([0, lMax], [Y0, Y1]);
  const ws = [3];
  for (let i = 1; i <= k; i++) ws.push(ws[i - 1] * f);
  const w = ws[k];
  const loss = L(w);
  const o = [];
  o.push(sdk.line('xaxis', X0, Y0, X1, Y0, { role: 'neutral' }));
  o.push(sdk.line('yaxis', X(0), Y0, X(0), Y1, { role: 'neutral', opacity: 0.4 }));
  o.push(sdk.line('yscale', X0, Y0, X0, Y1, { role: 'neutral', opacity: 0.6 }));
  const xt = big ? [-6, -3, 0, 3, 6] : [-3, -2, -1, 0, 1, 2, 3];
  xt.forEach((t) => o.push(sdk.text('xt' + (t + 6), X(t), Y0 + 20, String(t), { align: 'middle' })));
  const yt = big ? [10, 20] : [2, 4, 6];
  yt.forEach((t) => {
    o.push(sdk.line('ytk' + t, X0 - 5, Y(t), X0, Y(t), { role: 'neutral' }));
    o.push(sdk.text('yt' + t, X0 - 22, Y(t) + 4, String(t), { align: 'middle' }));
  });
  o.push(sdk.text('xlab', X1 - 10, Y0 + 44, 'w', { align: 'middle' }));
  o.push(sdk.math('ylab', X(0) + 14, Y1 + 4, 'L(w)=\\tfrac{w^2}{2}'));
  const span = wMax - (big ? 0.3 : 0.1);
  o.push(sdk.polyline('curve', sdk.sample(L, -span, span, 120).map(([a, b]) => [X(a), Y(b)]), { role: 'neutral' }));
  for (let i = 0; i < k; i++) {
    const x1 = X(ws[i]), y1 = Y(L(ws[i])), x2 = X(ws[i + 1]), y2 = Y(L(ws[i + 1]));
    if (Math.hypot(x2 - x1, y2 - y1) > 3) o.push(sdk.arrow('a' + i, x1, y1, x2, y2, { role: 'learner', opacity: 0.8 }));
  }
  for (let i = 0; i <= k; i++) {
    const cur = i === k;
    o.push(sdk.circle('p' + i, X(ws[i]), Y(L(ws[i])), cur ? 11 : 7, { role: cur ? 'output' : 'learner' }));
  }
  const px = 730;
  o.push(sdk.math('rule', px, 60, 'w_{k+1} = w_k - \\eta\\,w_k'));
  o.push(sdk.math('rule2', px + 30, 95, '= (1-\\eta)\\,w_k'));
  o.push(sdk.math('etat', px, 140, '\\eta = ' + sdk.format(eta, 1) + ',\\; 1-\\eta = ' + sdk.format(f, 1)));
  o.push(sdk.math('kt', px, 180, 'k = ' + k));
  o.push(sdk.math('wt', px, 220, 'w_{' + k + '} = ' + sdk.format(w, 3)));
  o.push(sdk.math('lt', px, 260, 'L(w_{' + k + '}) = ' + sdk.format(loss, 3)));
  let reg, role;
  if (eta < 1 && eta <= 0.5) { reg = 'Slow steady convergence'; role = 'success'; }
  else if (eta < 1) { reg = 'Fast convergence, same side'; role = 'success'; }
  else if (eta < 2) { reg = 'Overshoots shrink: converges'; role = 'prediction'; }
  else { reg = 'Overshoots grow: diverges'; role = 'warning'; }
  o.push(sdk.text('regime', px, 310, reg, { role }));
  o.push(sdk.math('ratio', px, 350, '|1-\\eta| = ' + sdk.format(Math.abs(f), 1) + (Math.abs(f) < 1 ? ' < 1' : ' > 1')));
  return {
    frame: sdk.frame(o, { width: 960, height: 540, readouts: [{ id: 'w_now', value: w }, { id: 'loss_now', value: loss }, { id: 'factor', value: f }] }),
    quantities: { w_now: w, loss_now: loss, factor: f, eta, k }
  };
}

